import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    // Un ADMIN central siempre ve todas las áreas por defecto
    if (user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN) {
      setGlobalFilterArea('ALL');
    } else {
      setGlobalFilterArea(user.area as Area);
    }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;

    // SuperAdmin y Admin Central ven todo el circuito.
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Roles de área ven solo su área si el ticket ya no está en Recibido (Bandeja Central)
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;

    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (req.status === target) return { allowed: true };

    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    if (req.status === Status.FINALIZADO) {
      return { allowed: false, reason: 'Expediente cerrado. Solo Auditoría Superior puede reabrir.' };
    }

    switch (activeRole) {
      case UserRole.ADMIN:
        // Admin solo gestiona la entrada (Recibido -> Derivación)
        if (req.status === Status.RECIBIDO && target === Status.DERIVACION) return { allowed: true };
        return { allowed: false, reason: 'El Admin Central solo gestiona la derivación inicial a Jefaturas.' };

      case UserRole.HEAD:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Este requerimiento pertenece a otra jurisdicción.' };

        // Derivación -> Ejecución: Requiere analista.
        if (req.status === Status.DERIVACION && target === Status.EJECUCION) {
          if (!req.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un responsable técnico antes de iniciar.' };
          return { allowed: true };
        }
        // Ejecución -> Finalizado: El Jefe puede cerrar si supervisa.
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Transición no permitida para Jefatura en este estado.' };

      case UserRole.ANALYST:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena.' };
        if (req.assignedAnalyst !== currentUser.name) return { allowed: false, reason: 'Solo el analista asignado al ticket puede certificar el cierre.' };
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Los analistas solo tienen facultad de cierre sobre tickets en ejecución.' };

      default:
        return { allowed: false, reason: 'Rol sin facultades operativas definidas.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal en SISREQ',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      isReturned: newStatus === Status.RECIBIDO ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ESTADO: Fase operativa actualizada a [${newStatus.toUpperCase()}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN: Ticket regresado a Central. Motivo: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: Responsable técnico asignado [${analystName}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'EDICIÓN: Actualización de especificaciones',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import React, { useMemo, useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Status, Area, Priority, SLA_DAYS } from '../types';
import { 
    BarChart3, TrendingUp, CheckCircle2, Clock, 
    Activity, AlertTriangle, CalendarRange, ArrowRight,
    Briefcase, Zap, Layers, Target, Calendar, ShieldCheck
} from 'lucide-react';

export const ReportsView: React.FC = () => {
  const { requests } = useSisreq();
  const [timeRange, setTimeRange] = useState<'Semanal' | 'Mensual' | 'Anual' | 'Todo'>('Mensual');

  const filteredRequests = useMemo(() => {
    if (timeRange === 'Todo') return requests;
    const now = new Date();
    return requests.filter(r => {
        const reqDate = new Date(r.createdAt);
        const diffTime = Math.abs(now.getTime() - reqDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (timeRange === 'Semanal') return diffDays <= 7;
        if (timeRange === 'Mensual') return diffDays <= 30;
        if (timeRange === 'Anual') return diffDays <= 365;
        return true;
    });
  }, [requests, timeRange]);

  const stats = useMemo(() => {
    const total = filteredRequests.length;
    const completed = filteredRequests.filter(r => r.status === Status.FINALIZADO);

    // Cálculo de SLA
    let slaComplianceCount = 0;
    completed.forEach(req => {
        if (req.finishedAt) {
            const start = new Date(req.createdAt).getTime();
            const end = new Date(req.finishedAt).getTime();
            const daysToComplete = (end - start) / (1000 * 60 * 60 * 24);
            if (daysToComplete <= SLA_DAYS[req.priority]) {
                slaComplianceCount++;
            }
        }
    });

    const slaRate = completed.length > 0 ? Math.round((slaComplianceCount / completed.length) * 100) : 0;
    const completionRate = total > 0 ? Math.round((completed.length / total) * 100) : 0;

    // Tiempo promedio
    let avgDays = 0;
    if (completed.length > 0) {
        const totalMs = completed.reduce((acc, curr) => {
            const start = new Date(curr.createdAt).getTime();
            const end = new Date(curr.finishedAt!).getTime();
            return acc + (end - start);
        }, 0);
        avgDays = Number((totalMs / (1000 * 60 * 60 * 24) / completed.length).toFixed(1));
    }

    const byStatus = [Status.RECIBIDO, Status.DERIVACION, Status.EJECUCION, Status.FINALIZADO].map(status => {
        const count = filteredRequests.filter(r => r.status === status).length;
        const percentage = total > 0 ? Math.round((count / total) * 100) : 0;
        return { name: status, count, percentage };
    });

    const byAreaEfficiency = Object.values(Area).map(area => {
        const areaRequests = filteredRequests.filter(r => r.area === area);
        const areaCompleted = areaRequests.filter(r => r.status === Status.FINALIZADO).length;
        const efficiency = areaRequests.length > 0 ? Math.round((areaCompleted / areaRequests.length) * 100) : 0;
        return { name: area, efficiency, total: areaRequests.length };
    });

    return { total, completed: completed.length, slaRate, completionRate, byStatus, avgDays, byAreaEfficiency };
  }, [filteredRequests]);

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 bg-[#F8FAFC]">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100">
                        <BarChart3 size={24} />
                    </div>
                    <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Inteligencia Operativa</h2>
                </div>
                <p className="text-slate-500 text-sm font-bold ml-1 flex items-center gap-2 mt-1">
                    <Calendar size={14} className="text-indigo-400" /> Periodo: <span className="text-indigo-600 font-black bg-indigo-50 px-3 py-0.5 rounded-full">{timeRange.toUpperCase()}</span>
                </p>
            </div>

            <div className="flex bg-white/80 backdrop-blur-sm p-1.5 rounded-[1.25rem] border border-slate-200 shadow-xl">
                {['Semanal', 'Mensual', 'Anual', 'Todo'].map((range) => (
                    <button
                        key={range}
                        onClick={() => setTimeRange(range as any)}
                        className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${
                            timeRange === range ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-800'
                        }`}
                    >
                        {range}
                    </button>
                ))}
            </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {[
                { label: 'Volumen Total', val: stats.total, icon: <Briefcase size={22}/>, color: 'bg-indigo-600', trend: 'Tickets' },
                { label: 'Cumplimiento SLA', val: `${stats.slaRate}%`, icon: <ShieldCheck size={22}/>, color: 'bg-emerald-600', trend: 'Meta > 85%' },
                { label: 'Eficiencia Global', val: `${stats.completionRate}%`, icon: <Target size={22}/>, color: 'bg-blue-600', trend: 'Cierres' },
                { label: 'Tiempo Medio', val: `${stats.avgDays}d`, icon: <Clock size={22}/>, color: 'bg-amber-500', trend: 'Lead Time' }
            ].map((card, i) => (
                <div key={i} className="bg-white p-7 rounded-[2rem] border border-slate-200/60 shadow-sm hover:-translate-y-2 transition-all group">
                    <div className="flex items-center justify-between mb-6">
                        <div className={`p-3.5 ${card.color} text-white rounded-2xl shadow-lg`}>
                            {card.icon}
                        </div>
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">{card.trend}</span>
                    </div>
                    <div>
                        <p className="text-4xl font-black text-slate-900 tracking-tighter">{card.val}</p>
                        <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mt-2">{card.label}</p>
                    </div>
                </div>
            ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8">
                <h3 className="font-black text-slate-900 uppercase tracking-tight text-lg flex items-center gap-3 mb-8">
                    <Layers size={22} className="text-indigo-600"/> Estados del Workflow
                </h3>
                <div className="space-y-8">
                    {stats.byStatus.map((step) => (
                        <div key={step.name} className="group">
                            <div className="flex justify-between items-end mb-3 text-xs font-black uppercase tracking-widest">
                                <span className="text-slate-500">{step.name}</span>
                                <span className="text-slate-900">{step.count} ({step.percentage}%)</span>
                            </div>
                            <div className="w-full h-3 bg-slate-100 rounded-full overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-1000 ${
                                        step.name === Status.FINALIZADO ? 'bg-emerald-500' : 'bg-indigo-400'
                                    }`}
                                    style={{ width: `${step.percentage}%` }}
                                ></div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-200 p-8">
                <h3 className="font-black text-slate-900 uppercase tracking-tight text-lg mb-8 flex items-center gap-3">
                    <Activity size={22} className="text-blue-500"/> Rendimiento por Área
                </h3>
                <div className="space-y-6">
                    {stats.byAreaEfficiency.map((area) => (
                        <div key={area.name} className="flex items-center gap-6">
                            <div className="w-32 shrink-0 text-xs font-black text-slate-500 uppercase tracking-wider">{area.name}</div>
                            <div className="flex-1 h-8 bg-slate-50 rounded-lg border border-slate-100 overflow-hidden relative">
                                <div 
                                    className="h-full bg-blue-500/20 border-r-2 border-blue-500 transition-all duration-1000"
                                    style={{ width: `${area.efficiency}%` }}
                                ></div>
                                <span className="absolute inset-0 flex items-center justify-center text-[10px] font-black text-blue-700">
                                    {area.efficiency}% EFICIENCIA ({area.total} REQ)
                                </span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    </div>
  );
};
